"""Package rebinding importlib later in the same function."""

import importlib

backend = importlib.import_module(name="late_shadow_pkg.backend")


def broken_loader():
    # The assignment below makes ``importlib`` function-local for the WHOLE
    # body, so this earlier call raises UnboundLocalError; bundling must not
    # rewrite it into bundled-module access.
    result = importlib.import_module(name="late_shadow_pkg.backend")
    importlib = None
    return result


def real_kind():
    return backend.KIND
